profile_overview.query:
query ProfileOverview($cursor: String!, $filters: ProfileSearchFiltersInput!, $isAd: Boolean) {
  profiles: profileSearch(filters: $filters, limit: 30, cursor: $cursor, isAd: $isAd) {
    ...OverviewProfile
    __typename
  }
  __typename
}

fragment OverviewProfile on Profile {
  ...MinimalProfile
  primaryImageAd {
    ...MinimalUploadedImage
    __typename
  }
  location {
    ...ProfileLocation
    __typename
  }
  temporaryStatus {
    ...ProfileTemporaryStatus
    __typename
  }
  __typename
}

fragment MinimalProfile on Profile {
  id
  uuid
  displayName
  username
  relationType
  roles
  primaryImage {
    ...MinimalUploadedImage
    __typename
  }
  __typename
}

fragment MinimalUploadedImage on UploadedImage {
  id
  uuid
  url
  contentRating
  blurHash
  __typename
}

fragment ProfileLocation on ProfileLocation {
  type
  distance
  place {
    ...Place
    __typename
  }
  homePlace {
    ...Place
    __typename
  }
  __typename
}

fragment Place on Place {
  id
  place
  region
  country
  countryCode
  longitude
  latitude
  __typename
}

fragment ProfileTemporaryStatus on ProfileTemporaryStatus {
  id
  status
  createdAt
  expiredAt
  __typename
}

profile_detail.query:
query ProfileDetail($uuid: String!, $location: SearchLocationInput) {
  profile(uuid: $uuid, location: $location) {
    ...DetailProfile
    __typename
  }
  __typename
}

